    ...light, ...(light.appearance ? { appearance: resolveAppearance(light.appearance) } : {}), typography: cloneTypography(light.typography), densityOverrides: validateDensityOverrides(light.densityOverrides), componentSpacing: validateComponentSpacing(light.componentSpacing),
